local KTool = CS.Engine.Lib.KTool
---@class OverseaManagePersonnelSelectCatCell
local OverseaManagePersonnelSelectCatCell = Class('OverseaManagePersonnelSelectCatCell')
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
local CatHouseCaptureTextureComplete = Constants.EventNames.CatHouseCaptureTextureComplete

function OverseaManagePersonnelSelectCatCell:__init()
    
end


function OverseaManagePersonnelSelectCatCell:Awake()
    SetButtonAction(self.BtnDelete,Bind(self,self.OnBtnDelClick))
    SetButtonAction(self.BtnNode,Bind(self,self.OnBtnNodeClick))
end

function OverseaManagePersonnelSelectCatCell:RegEvent()
    if self.__EventCaptureTextureCompleteAction then
        return
    end
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end


function OverseaManagePersonnelSelectCatCell:__delete()
    
end

function OverseaManagePersonnelSelectCatCell:RefreshChooseStatus(isIn,index)
    self:SetChooseStatus(isIn)
    if isIn then
        CfUtils.FillText(self.ChoosePosText,index)
    end
end

function OverseaManagePersonnelSelectCatCell:RefreshRoleData(data,callBack,index)
    self.callBack = callBack
    self.data = data
    self.index = index
    self:SetHeadNode()
end

function OverseaManagePersonnelSelectCatCell:SetChooseStatus(status)
    KTool.SetActive(self.Choose.gameObject,status)
end

function OverseaManagePersonnelSelectCatCell:SetSelectStatus(status)
    KTool.SetActive(self.ImgSelect.gameObject,status)
end

function OverseaManagePersonnelSelectCatCell:RefreshSelectStatus(selectIndex)
    if not isNull(selectIndex) and selectIndex == self.index then
        self:SetSelectStatus(true)
    else
        self:SetSelectStatus(false)
    end
end

function OverseaManagePersonnelSelectCatCell:SetHeadNode()
    self:RegEvent()
    ---@type MaidCoffeeCatRollConfigVo
    local vo      = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(self.data.catId)
    CfUtils.FillText(self.CatName,vo.name)
    local genes = self.data ~= nil and self.data.genes or vo.kind1
    self:CaptureTexture(vo.catId, genes)
end

function OverseaManagePersonnelSelectCatCell:CaptureTexture(catId,genes)
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, catId, genes)
    self._fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(catId), genes,false, fileNameId)
end

function OverseaManagePersonnelSelectCatCell:OnEventCaptureTextureCompleteAction(id, path)
    if self._fileNameId ~= id then return end
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    ---@type UnityEngine.UI.RawImage
    local  rawImage = KTool.GetComponent(self.ImgIconCat.gameObject, typeof(CS.UnityEngine.UI.RawImage))
    rawImage.texture = texture
    KTool.SetActive(self.ImgIconCat.gameObject, true)
end

function OverseaManagePersonnelSelectCatCell:OnBtnNodeClick()
    if self.callBack then
        self.callBack(false)
    end
end

function OverseaManagePersonnelSelectCatCell:Start()
end

function OverseaManagePersonnelSelectCatCell:OnBtnDelClick()
    ---点击的事件执行
    if self.callBack then
        self.callBack(true)
    end
end

function OverseaManagePersonnelSelectCatCell:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManagePersonnelSelectCatCell